ausstattung_persoenliche_innenlast <- function(ausstattungsbetrag=NULL,gesamtgutangemessener_betrag=NULL,zugestimmter_mehrbetrag=NULL,berechnungsfall=NULL,zuordnungsnachweis=NULL) {
  ausstattung <- .geld(ausstattungsbetrag);angemessen <- .geld(gesamtgutangemessener_betrag);zustimmung <- .geld(zugestimmter_mehrbetrag)
  .text(berechnungsfall,"berechnungsfall");.text(zuordnungsnachweis,"zuordnungsnachweis")
  faelle <- c("gemeinschaftliches_kind_alleinverwalter","nichtgemeinschaftliches_kind_elternteil_alleinverwalter","nichtgemeinschaftliches_kind_elternteil_nichtverwalter","nichtgemeinschaftliches_kind_gemeinschaftliche_verwaltung")
  if (!(berechnungsfall %in% faelle)) .fehler("berechnungsfall","Qualifizierter gesetzlicher Berechnungsfall nach\u00a71444 oder\u00a71466 erforderlich.")
  grundbetrag <- if (.vergleichen(ausstattung,angemessen)<=0) ausstattung else angemessen
  mehrbetrag <- .subtrahieren(ausstattung,grundbetrag)
  if (.vergleichen(zustimmung,mehrbetrag)>0) .fehler("zugestimmter_mehrbetrag","Zugestimmter Mehrbetrag darf den tats\u00e4chlich \u00fcber dem Gesamtgutma\u00df liegenden Betrag nicht \u00fcbersteigen.")
  if (berechnungsfall!="nichtgemeinschaftliches_kind_elternteil_nichtverwalter" && .vergleichen(zustimmung,.bruch(0))!=0) .fehler("zugestimmter_mehrbetrag","Zustimmungsmehrbetrag nur im Nichtverwalter-Elternfall verwenden; sonst null.")
  last <- if (berechnungsfall=="gemeinschaftliches_kind_alleinverwalter") mehrbetrag else if (berechnungsfall=="nichtgemeinschaftliches_kind_elternteil_nichtverwalter") .addieren(grundbetrag,zustimmung) else ausstattung
  eingaben <- list(ausstattungsbetrag=ausstattungsbetrag,gesamtgutangemessener_betrag=gesamtgutangemessener_betrag,zugestimmter_mehrbetrag=zugestimmter_mehrbetrag,berechnungsfall=berechnungsfall,zuordnungsnachweis=zuordnungsnachweis)
  wert <- list(persoenliche_innenlast=.bruchteile(last),nicht_als_persoenliche_innenlast_erfasst=.bruchteile(.subtrahieren(ausstattung,last)))
  ergebnis <- .ergebnis(wert,"EUR","BGB_AUSSTATTUNG_PERSOENLICHE_INNENLAST",eingaben,list(list(operation="Gemeinschaftliches Kind: nur Mehrbetrag des Alleinverwalters; nichtgemeinschaftliches Kind: Elternteil volle Last, bei Nichtverwaltung nur Gesamtgutma\u00df plus konkret zugestimmtem Mehrbetrag.")),eingaben)
  ergebnis$hinweise <- list("Gesetzliche Innenlast ohne abweichende Vereinbarung. Bei gemeinschaftlichem Kind nach\u00a71444I ist die pers\u00f6nliche Last des allein verwaltenden Ehegatten gemeint. Bei nichtgemeinschaftlichem Kind ist die pers\u00f6nliche Last des Elternteils gemeint:\u00a71444II bei Alleinverwaltung,\u00a71466 bei gemeinschaftlicher Verwaltung. Umfang der Ausstattung und Gesamtgutma\u00df rechtlich bewertet; keine automatische Bestimmung von Elternschaft, Kindeseigenschaft, Verwaltungsform oder Angemessenheit. Im Nichtverwalter-Elternfall Zustimmung ausschlie\u00dflich als tats\u00e4chlich zugestimmter Teil des \u00fcber dem Ma\u00df liegenden Mehrbetrags vorgeben; nicht pauschal irgendeinen zugestimmten Gesamtbetrag verwenden, da sonst \u00dcberlappungen doppelt z\u00e4hlen. \u00dcbriger Betrag wird nur als nicht dieser pers\u00f6nlichen Last zugeordnet ausgewiesen, nicht automatisch dem anderen Ehegatten oder einer Masse auferlegt. Keine Au\u00dfenhaftung, Erf\u00fcllung, Schenkungsbewertung oder Ausgleichsf\u00e4lligkeit berechnet.")
  ergebnis
}
